CREATE OR REPLACE FUNCTION public.ct_admin_order_action(p_operation_id uuid,p_action text,p_order bigint,p_values jsonb,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required';END IF;IF p_action='correction' AND EXISTS(SELECT 1 FROM public.ct_orders WHERE id=p_order AND crypto_payment IS NOT NULL) THEN RAISE EXCEPTION 'Une commande crypto ne peut pas être corrigée en crédits ou diamants';END IF;RETURN public.ct_admin_order_action_before_crypto(p_operation_id,p_action,p_order,p_values,p_reason);END $$;
REVOKE ALL ON FUNCTION public.ct_admin_order_action(uuid,text,bigint,jsonb,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.ct_admin_order_action(uuid,text,bigint,jsonb,text) TO authenticated;
